#!/usr/bin/env python3
"""Дорогой тир окупается или нет — и это ответ числами, а не мнением.

Откуда это взялось. Числа в системе собирались честно и никуда не вели. Цена
прогона считалась по журналам сессий, выбор тира со всеми признаками ложился в
ход стройки, счётчик заходов вёлся проверкой — и ни один из трёх никто не читал,
чтобы в следующий раз решить иначе. Накопление без обратной связи выглядит как
самоулучшение ровно до того дня, когда кто-нибудь спросит, за что мы платим.

Что здесь заперто:

  · признак, после которого заходов МЕНЬШЕ, и признак, после которого их
    столько же, различаются ПО ЧИСЛАМ и получают разные вердикты;
  · ниже порога записей ответ — «мерить нечем», а не осторожная догадка;
    порог назван числом и виден в ответе;
  · журнала сессий нет — сказано «расход не измерен», а не подставлен ноль:
    отсутствие данных и нулевая трата — разные утверждения;
  · журнал сессий есть — цена захода берётся у СУЩЕСТВУЮЩЕГО измерителя, и
    сумма разнесённых цен равна измеренной цене сессии;
  · подозрительный признак ПОКАЗАН вместе с тем, кто по нему решает: ход
    стройки после прогона байт в байт прежний, инструмент не выключает ничего;
  · счётчик заходов один: подсунутый счётчик проверки на ответ не влияет;
  · группа сравнения — обычный тир: дешёвый в неё не идёт, иначе признак
    обвиняли бы лёгкостью механических правок;
  · признак, живущий на заходах, которых у группы сравнения нет, сравнивать не
    с чем — и это сказано, а не подменено вердиктом;
  · обратный контроль: на здоровых данных подозрительным не объявляется ничто.

Окружение каждого запуска собирается с нуля: `HOME` внутрь temp, `PATH` пуст.
Настоящие журналы сессий человека тест не читает НИКОГДА: измеритель ищет их в
домашнем каталоге, а домашний каталог здесь свой.

Тест самодостаточен: только стандартная библиотека и сами инструменты.

  python3 -m pytest tests/external/test_routing_pays_off.py -q
"""
from __future__ import annotations

import importlib.util
import json
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

РЕПО = Path(__file__).resolve().parents[2]
ИНСТРУМЕНТЫ = РЕПО / "plugins" / "superstack" / "tools"
ОКУПАЕМОСТЬ = ИНСТРУМЕНТЫ / "tier_payoff.py"
ИЗМЕРИТЕЛЬ = ИНСТРУМЕНТЫ / "measure_run.py"
ФАЗА_ОТЧЁТА = (РЕПО / "plugins" / "superstack" / "skills" / "go" / "phases"
               / "8-отчёт.md")


def _загрузить(имя: str, путь: Path):
    спек = importlib.util.spec_from_file_location(имя, путь)
    мод = importlib.util.module_from_spec(спек)
    sys.modules[имя] = мод
    спек.loader.exec_module(мод)
    return мод


окупаемость = _загрузить("ss_a18_payoff", ОКУПАЕМОСТЬ)
измеритель = _загрузить("ss_a18_measure", ИЗМЕРИТЕЛЬ)

ДОРОГОЙ = окупаемость.ДОРОГОЙ
ОБЫЧНЫЙ = окупаемость.ОБЫЧНЫЙ
ДЕШЁВЫЙ = "haiku"

#: Окно, в которое укладываются все проверочные записи выбора. Час выбран
#: с запасом: записи идут по секунде, и их меньше сотни.
НАЧАЛО = "2026-09-08T03:00:00+00:00"
КОНЕЦ = "2026-09-08T04:00:00+00:00"


def когда(секунда: int) -> str:
    м, с = divmod(секунда, 60)
    return f"2026-09-08T03:{м:02d}:{с:02d}+00:00"


class База(unittest.TestCase):
    """Проект с ходом стройки, свой домашний каталог и запуск инструмента."""

    def setUp(self):
        self.врем = tempfile.TemporaryDirectory()
        корень = Path(self.врем.name)
        self.дом = корень / "дом"
        self.проект = корень / "проект"
        (self.проект / ".superstack").mkdir(parents=True)
        self.дом.mkdir()
        self.состояние = self.проект / ".superstack" / "state.json"
        self.секунда = 0
        self.addCleanup(self.врем.cleanup)

    # ---- подготовка ---------------------------------------------------
    def запись(self, задача: str, заход: int, тир: str, признаки: list) -> dict:
        """Строка журнала выбора в том виде, в каком её пишет маршрутизатор."""
        self.секунда += 1
        return {
            "task": задача, "tier": тир, "attempt": заход,
            "why": f"{тир} — проверочная запись",
            "signals": [{"признак": п, "почему": "проверочный признак"}
                        for п in признаки],
            "delivery": {"состояние": "доезжает", "почему": "проверка"},
            "at": когда(self.секунда),
        }

    def группа(self, префикс: str, сколько: int, перезаходов: int,
               тир: str, признаки: list) -> tuple:
        """Столько задач; у первых `перезаходов` из них был второй заход.

        Второй заход пишется так, как его написал бы маршрутизатор: дорогим
        тиром и с добавленным признаком повторного захода.
        """
        задачи, журнал = [], []
        for i in range(сколько):
            tid = f"{префикс}{i:02d}"
            задачи.append({"id": tid, "name": f"часть {tid}",
                           "status": "proven"})
            журнал.append(self.запись(tid, 1, тир, признаки))
            if i < перезаходов:
                журнал.append(self.запись(tid, 2, ДОРОГОЙ,
                                          признаки + ["повторный заход"]))
        return задачи, журнал

    def стройка(self, *группы) -> Path:
        задачи, журнал = [], []
        for з, ж in группы:
            задачи += з
            журнал += ж
        self.состояние.write_text(json.dumps(
            {"schema": "superstack.progress.v1", "project": "проверка",
             "waves": {"1": задачи}, окупаемость.ЖУРНАЛ: журнал},
            ensure_ascii=False), encoding="utf-8")
        return self.состояние

    def журнал_сессии(self, ходов: int = 4, выход: int = 1000) -> Path:
        """Журнал сессии в том виде, в каком его пишет хост.

        Кладётся в ПОДСТАВНОЙ домашний каталог: имя каталога считает сам
        измеритель, чтобы тест и код не разошлись в правиле именования.
        """
        куда = (self.дом / ".claude" / "projects"
                / измеритель.logs_dir(self.проект).name)
        куда.mkdir(parents=True, exist_ok=True)
        строки = []
        for i in range(ходов):
            метка = НАЧАЛО if i == 0 else (КОНЕЦ if i == ходов - 1
                                           else когда(i))
            строки.append(json.dumps({
                "timestamp": метка,
                "message": {"id": f"msg{i}",
                            "usage": {"output_tokens": выход,
                                      "cache_cre" "ation_inp" "ut_tokens": 0,
                                      "cache_read_input_tokens": 0,
                                      "input_tokens": 0}}}))
        файл = куда / "сессия.jsonl"
        файл.write_text("\n".join(строки) + "\n", encoding="utf-8")
        return файл

    # ---- запуск -------------------------------------------------------
    def запустить(self, *аргументы, среда: dict = None
                  ) -> subprocess.CompletedProcess:
        окружение = {
            "HOME": str(self.дом),
            "PATH": "",
            "PYTHONUTF8": "1",
            "PYTHONIOENCODING": "utf-8",
            "SUPERSTACK_IGNORE_PAUSE": "1",
        }
        окружение.update(среда or {})
        return subprocess.run([sys.executable, str(ОКУПАЕМОСТЬ), *аргументы],
                              env=окружение, capture_output=True, text=True,
                              timeout=300, cwd=str(self.проект))

    def свести(self, *аргументы, ожидаем: int = 0, среда: dict = None) -> dict:
        p = self.запустить(str(self.состояние), *аргументы, "--json",
                           среда=среда)
        self.assertEqual(p.returncode, ожидаем,
                         f"код {p.returncode}\n{p.stdout[-600:]}\n"
                         f"{p.stderr[-900:]}")
        self.последний = p
        return json.loads(p.stdout)

    def признак(self, v: dict, имя: str) -> dict:
        найден = next((с for с in v["signals"] if с["признак"] == имя), None)
        self.assertIsNotNone(найден, f"признака «{имя}» нет в ответе: {v}")
        return найден


# ==========================================================================
# окупается или нет — разные числа и разные вердикты
# ==========================================================================
class ОкупаемостьСчитаетсяЧислами(База):
    """Тот же вопрос, что задал бы владелец: за что мы платим дороже.

    Два дорогих признака в одном прогоне: после первого заходов почти не бывает,
    после второго их столько же, сколько без всякой доплаты.
    """

    def смешанный(self) -> dict:
        return self.свести(ожидаем=1)

    def setUp(self):
        super().setUp()
        self.стройка(
            self.группа("A", 12, 1, ДОРОГОЙ, ["под решением"]),
            self.группа("B", 12, 8, ДОРОГОЙ, ["данные человека"]),
            self.группа("C", 14, 2, ОБЫЧНЫЙ, []))

    def test_окупившийся_и_неокупившийся_признаки_различаются_по_числам(self):
        v = self.смешанный()
        решение = self.признак(v, "под решением")
        данные = self.признак(v, "данные человека")
        self.assertLess(решение["доля"], данные["доля"], v)
        self.assertEqual(решение["вердикт"], окупаемость.ОКУПАЕТСЯ, решение)
        self.assertEqual(данные["вердикт"], окупаемость.ПОДОЗРИТЕЛЬНЫЙ, данные)

    def test_подозрительный_признак_назван_поимённо(self):
        v = self.смешанный()
        self.assertEqual(v["suspicious"], ["данные человека"], v)
        self.assertEqual(v["status"], "fail", v)

    def test_числа_приведены_а_не_только_вердикт(self):
        данные = self.признак(self.смешанный(), "данные человека")
        self.assertEqual(данные["записей"], 20, данные)
        self.assertEqual(данные["перезаходов"], 8, данные)
        self.assertEqual(данные["закрыто"], 20, данные)

    def test_группа_сравнения_это_выборы_обычного_тира(self):
        v = self.смешанный()
        основа = v["baseline"]
        self.assertEqual(основа["записей"], 14, основа)
        self.assertEqual(основа["перезаходов"], 2, основа)

    def test_дешёвый_тир_в_группу_сравнения_не_идёт(self):
        # Дешёвый тир достаётся механическим правкам: вторых заходов у них
        # почти не бывает и без всякой доплаты. Считая их «жизнью без
        # признака», инструмент обвинял бы признаки чужой лёгкостью.
        self.стройка(
            self.группа("A", 12, 1, ДОРОГОЙ, ["под решением"]),
            self.группа("C", 14, 6, ОБЫЧНЫЙ, []),
            self.группа("D", 20, 0, ДЕШЁВЫЙ, ["механическая правка"]))
        основа = self.свести(ожидаем=0)["baseline"]
        self.assertEqual(основа["записей"], 14, основа)
        self.assertEqual(основа["перезаходов"], 6, основа)

    def test_вердикт_объясняется_словами_а_не_только_числом(self):
        данные = self.признак(self.смешанный(), "данные человека")
        self.assertTrue(данные["почему"].strip(), данные)
        self.assertIn("перезаход", данные["почему"], данные)


# ==========================================================================
# мало данных — «мерить нечем», а не догадка
# ==========================================================================
class МалоДанных(База):

    def test_шести_записей_на_вывод_не_хватает(self):
        # Пять записей вывода не дают, и шесть тоже. Порог — свойство прибора,
        # а не настроение читающего.
        self.стройка(
            self.группа("B", 6, 0, ДОРОГОЙ, ["данные человека"]),
            self.группа("C", 14, 2, ОБЫЧНЫЙ, []))
        v = self.свести(ожидаем=2)
        данные = self.признак(v, "данные человека")
        self.assertEqual(данные["вердикт"], окупаемость.НЕЧЕМ, данные)
        self.assertEqual(v["status"], "unknown", v)

    def test_порог_назван_числом_в_ответе(self):
        self.стройка(
            self.группа("B", 6, 0, ДОРОГОЙ, ["данные человека"]),
            self.группа("C", 14, 2, ОБЫЧНЫЙ, []))
        v = self.свести(ожидаем=2)
        self.assertEqual(v["threshold"], окупаемость.ПОРОГ_ЗАПИСЕЙ, v)
        данные = self.признак(v, "данные человека")
        self.assertIn(str(окупаемость.ПОРОГ_ЗАПИСЕЙ), данные["почему"], данные)

    def test_ниже_порога_вердикта_нет_даже_когда_числа_красивые(self):
        # Шесть записей без единого перезахода выглядят как безупречно
        # окупившийся признак. Это и есть та осторожная догадка, ради запрета
        # которой порог существует.
        self.стройка(
            self.группа("B", 6, 0, ДОРОГОЙ, ["данные человека"]),
            self.группа("C", 14, 6, ОБЫЧНЫЙ, []))
        данные = self.признак(self.свести(ожидаем=2), "данные человека")
        self.assertEqual(данные["вердикт"], окупаемость.НЕЧЕМ, данные)

    def test_журнала_выбора_нет_это_нечем_мерить_а_не_ноль(self):
        self.состояние.write_text(json.dumps(
            {"schema": "superstack.progress.v1", "waves": {"1": []}}),
            encoding="utf-8")
        v = self.свести(ожидаем=2)
        self.assertEqual(v["status"], "unknown", v)
        self.assertEqual(v["records"], 0, v)

    def test_дорогой_тир_ни_разу_не_выбирался_окупаться_нечему(self):
        self.стройка(self.группа("C", 14, 0, ОБЫЧНЫЙ, []))
        v = self.свести(ожидаем=2)
        self.assertEqual(v["signals"], [], v)
        self.assertEqual(v["status"], "unknown", v)

    def test_признак_с_чужими_заходами_сравнивать_не_с_чем(self):
        # «Повторный заход» по устройству срабатывает лишь после провала, а на
        # повторном заходе обычного тира не бывает вовсе. Сравнивать было бы не
        # с чем, и вердикт тут вышел бы формой, а не измерением. Проверяются
        # НОМЕРА заходов: имя признака в измеритель зашивать нельзя.
        self.стройка(
            self.группа("B", 12, 12, ДОРОГОЙ, ["данные человека"]),
            self.группа("C", 14, 2, ОБЫЧНЫЙ, []))
        v = self.свести(ожидаем=1)
        повтор = self.признак(v, "повторный заход")
        self.assertEqual(повтор["вердикт"], окупаемость.НЕЧЕМ, повтор)
        self.assertIn("разные наборы задач", повтор["почему"], повтор)
        # Не спутать с отказом по тонкой группе сравнения: она тут толстая.
        self.assertGreaterEqual(v["baseline"]["закрыто"],
                                окупаемость.ПОРОГ_ЗАПИСЕЙ, v)


# ==========================================================================
# расход: берётся у измерителя или называется отсутствующим
# ==========================================================================
class Расход(База):

    def setUp(self):
        super().setUp()
        self.стройка(
            self.группа("A", 12, 1, ДОРОГОЙ, ["под решением"]),
            self.группа("B", 12, 8, ДОРОГОЙ, ["данные человека"]),
            self.группа("C", 14, 2, ОБЫЧНЫЙ, []))

    def test_журнала_сессий_нет_это_сказано_а_не_подставлено_нулём(self):
        v = self.свести(ожидаем=1)
        self.assertFalse(v["spend"]["измерен"], v["spend"])
        self.assertIn(окупаемость.РАСХОД_НЕ_ИЗМЕРЕН, v["spend"]["почему"],
                      v["spend"])
        for с in v["signals"]:
            self.assertIsNone(с["цена"], с)

    def test_без_расхода_вывод_по_заходам_всё_равно_даётся(self):
        # «Цену не измерили» не значит «ничего не известно»: заходы посчитаны,
        # и молчать о них было бы отказом от единственного, что измерено.
        v = self.свести(ожидаем=1)
        self.assertEqual(v["suspicious"], ["данные человека"], v)

    def test_цена_берётся_у_измерителя_прогона_а_не_считается_заново(self):
        self.журнал_сессии(ходов=4, выход=1000)
        v = self.свести(ожидаем=1)
        self.assertTrue(v["spend"]["измерен"], v["spend"])
        for с in v["signals"]:
            self.assertIsNotNone(с["цена"], с)

    def test_разнесённая_цена_в_сумме_равна_измеренной(self):
        # Второй источник расхода разошёлся бы с первым; здесь их один, и
        # равенство сумм это доказывает.
        файл = self.журнал_сессии(ходов=4, выход=1000)
        замер = измеритель.measure_file(файл)
        v = self.свести(ожидаем=1)
        self.assertAlmostEqual(v["spend"]["разнесено"], замер["cost"], places=3)

    def test_выбор_вне_измеренной_сессии_ценой_не_наделяется(self):
        # Запись, не попавшая ни в одно измеренное окно, остаётся без цены.
        # Растянуть на неё среднее значило бы выдумать расход.
        self.журнал_сессии(ходов=4, выход=1000)
        данные = json.loads(self.состояние.read_text("utf-8"))
        данные[окупаемость.ЖУРНАЛ][0]["at"] = "2020-01-01T00:00:00+00:00"
        self.состояние.write_text(json.dumps(данные, ensure_ascii=False),
                                  encoding="utf-8")
        v = self.свести(ожидаем=1)
        self.assertEqual(v["spend"]["без_цены"], 1, v["spend"])


# ==========================================================================
# показывает, а не выключает
# ==========================================================================
class РешаетВладелец(База):

    def setUp(self):
        super().setUp()
        self.стройка(
            self.группа("B", 12, 8, ДОРОГОЙ, ["данные человека"]),
            self.группа("C", 14, 2, ОБЫЧНЫЙ, []))

    def test_ход_стройки_после_прогона_байт_в_байт_прежний(self):
        было = self.состояние.read_bytes()
        self.свести(ожидаем=1)
        self.assertEqual(self.состояние.read_bytes(), было)

    def test_у_каждого_вердикта_назван_тот_кто_решает(self):
        данные = self.признак(self.свести(ожидаем=1), "данные человека")
        self.assertEqual(данные["решает"], окупаемость.ВЛАДЕЛЕЦ, данные)

    def test_человеку_сказано_что_ничего_не_выключено(self):
        p = self.запустить(str(self.состояние))
        self.assertEqual(p.returncode, 1, p.stderr[-500:])
        self.assertIn("не выключа", p.stdout)

    def test_в_тексте_человеку_нет_терминальных_команд(self):
        p = self.запустить(str(self.состояние))
        for запрет in ("python3", "$", "--json", "pytest"):
            self.assertNotIn(запрет, p.stdout, f"в тексте человеку: {запрет}")


# ==========================================================================
# счётчик заходов один
# ==========================================================================
class СчётчикЗаходовОдин(База):

    def test_подсунутый_счётчик_проверки_на_ответ_не_влияет(self):
        # Третий счётчик разошёлся бы с журналом выбора и начал бы спорить
        # ровно тогда, когда нужен точный ответ.
        self.стройка(
            self.группа("B", 12, 8, ДОРОГОЙ, ["данные человека"]),
            self.группа("C", 14, 2, ОБЫЧНЫЙ, []))
        свои = self.свести(ожидаем=1)
        чужой = self.проект / "verify-attempts.json"
        чужой.write_text(json.dumps(
            {str(self.проект.resolve()): {"attempt": 9, "sig": "тесты"}}),
            encoding="utf-8")
        с_чужим = self.свести(ожидаем=1,
                              среда={"SUPERSTACK_VERIFY_STATE": str(чужой)})
        self.assertEqual(свои["signals"], с_чужим["signals"])

    def test_перезаход_считается_по_журналу_выбора(self):
        self.стройка(
            self.группа("B", 12, 8, ДОРОГОЙ, ["данные человека"]),
            self.группа("C", 14, 2, ОБЫЧНЫЙ, []))
        данные = self.признак(self.свести(ожидаем=1), "данные человека")
        self.assertEqual(данные["перезаходов"], 8, данные)

    def test_незакрытая_задача_исходом_не_считается(self):
        # Заход, после которого ничего не известно, — не «сошлось». Считать
        # его удачей значит красить незаконченное в зелёное.
        self.стройка(
            self.группа("B", 12, 0, ДОРОГОЙ, ["данные человека"]),
            self.группа("C", 14, 2, ОБЫЧНЫЙ, []))
        данные = json.loads(self.состояние.read_text("utf-8"))
        for т in данные["waves"]["1"]:
            if т["id"].startswith("B0"):
                т["status"] = "running"
        self.состояние.write_text(json.dumps(данные, ensure_ascii=False),
                                  encoding="utf-8")
        v = self.свести(ожидаем=2)
        данные_признак = self.признак(v, "данные человека")
        self.assertEqual(данные_признак["записей"], 12, данные_признак)
        self.assertLess(данные_признак["закрыто"], 12, данные_признак)
        self.assertGreater(v["unresolved"], 0, v)


# ==========================================================================
# обратный контроль
# ==========================================================================
class НаЗдоровыхДанныхТихо(База):

    def test_окупающийся_признак_подозрительным_не_объявляется(self):
        self.стройка(
            self.группа("A", 12, 1, ДОРОГОЙ, ["под решением"]),
            self.группа("C", 14, 6, ОБЫЧНЫЙ, []))
        v = self.свести(ожидаем=0)
        self.assertEqual(v["suspicious"], [], v)
        self.assertEqual(v["status"], "pass", v)
        self.assertEqual(self.признак(v, "под решением")["вердикт"],
                         окупаемость.ОКУПАЕТСЯ, v)

    def test_группа_сравнения_ниже_порога_это_не_вердикт(self):
        # Сравнить не с чем — тоже «мерить нечем», и подменять это выводом
        # нельзя: без второй группы разницы не существует.
        self.стройка(
            self.группа("A", 12, 1, ДОРОГОЙ, ["под решением"]),
            self.группа("C", 4, 1, ОБЫЧНЫЙ, []))
        решение = self.признак(self.свести(ожидаем=2), "под решением")
        self.assertEqual(решение["вердикт"], окупаемость.НЕЧЕМ, решение)
        self.assertIn("сравн", решение["почему"], решение)

    def test_битый_ход_стройки_это_ошибка_вызова(self):
        self.состояние.write_text("{не json", encoding="utf-8")
        p = self.запустить(str(self.состояние), "--json")
        self.assertEqual(p.returncode, 3, p.stderr[-500:])

    def test_нет_хода_стройки_это_ошибка_вызова(self):
        p = self.запустить(str(self.проект / ".superstack" / "нет.json"),
                           "--json")
        self.assertEqual(p.returncode, 3, p.stderr[-500:])


# ==========================================================================
# инструмент достижим
# ==========================================================================
class ЕгоКтоТоЗовёт(unittest.TestCase):
    """Инструмент, который не с чего запустить, неотличим от отсутствующего.

    Ворота проводки считают достижимость по всему пакету; здесь заперто
    конкретное место вызова — фаза отчёта, где цена прогона уже измеряется.
    Отвязать инструмент от неё молча теперь нельзя.
    """

    def test_фаза_отчёта_зовёт_свод_окупаемости(self):
        текст = ФАЗА_ОТЧЁТА.read_text("utf-8")
        self.assertIn("tier_payoff.py", текст)

    def test_фаза_отчёта_по_прежнему_меряет_расход(self):
        # Свод окупаемости читает измеренное, а не заменяет измерение.
        текст = ФАЗА_ОТЧЁТА.read_text("utf-8")
        self.assertIn("measure_run.py", текст)


if __name__ == "__main__":
    unittest.main()
